using System;using System.Collections.Generic;using System.IO;using System.Web.Script.Serialization;using System.Globalization;using AFramePlugin;
class SnapshotProbe{static void Main(string[] args){var j=new JavaScriptSerializer();var s=FrameSolutionSelection.FromDict(j.DeserializeObject(File.ReadAllText(args[0])));s.geometry.insulation_layers_mm=new List<double>{76.53,58.41,186.72,120.77,17.39};s.geometry.cladding_front_offset_mm=null;
var project=FrameProjectParameters.CreateNext(null,s,"0123456789abcdef0123456789abcdef");var zone=FrameZoneParameters.CreateNext(null,project,new Dictionary<string,FrameParameterOverride>());var resolved=FrameParameterResolver.Resolve(project,new string('a',64),zone,new string('b',64),"A1","Z1");
var input=FrameNodeGeometryInput.CreateDefault();input.clearance_surface.kind=FrameNodeClearanceSurface.Layers;input.profile_near_face_x_mm=BitConverter.Int64BitsToDouble(BitConverter.DoubleToInt64Bits(479.82)+1);
var snap=FrameNodeSnapshot.Create(s,resolved.Context,input,"2026-10-01T00:00:00.0000000Z");var dict=snap.ToDict();string serialized=j.Serialize(dict);var raw=(Dictionary<string,object>)j.DeserializeObject(serialized);var rawInput=(Dictionary<string,object>)raw["input"];var n=rawInput["profile_near_face_x_mm"];
try{var back=FrameNodeSnapshot.FromDict(raw);Console.WriteLine(j.Serialize(new{status="roundtrip_success",profile_before=input.profile_near_face_x_mm,profile_after=back.Input.profile_near_face_x_mm,gap_before=snap.Result.GapText,gap_after=back.Result.GapText}));}
catch(FrameNodeGeometryException e){Console.WriteLine(j.Serialize(new{status="roundtrip_refusal",code=e.Code,message=e.Message,profile_before=input.profile_near_face_x_mm.Value.ToString("R",CultureInfo.InvariantCulture),parsed_type=n.GetType().Name,parsed_text=Convert.ToString(n,CultureInfo.InvariantCulture),converted_double=Convert.ToDouble(n).ToString("R",CultureInfo.InvariantCulture),via_double_parse=double.Parse(Convert.ToString(n,CultureInfo.InvariantCulture),CultureInfo.InvariantCulture).ToString("R",CultureInfo.InvariantCulture),gap_before=snap.Result.GapText}));}
}}
